// get descriptions
let describe = global.get('describe', 'default');

// Remove dirty code
let lines = msg.payload.toString().replace("\u0002\n","").replace("\r\u0003","");
msg.payload = {};

// Split message by line
lines = lines.split("\r\n");
for (const line in lines) {

	// Prepare checksum
	let i;
	let checksum = 32;
	let myline = lines[line].toString().replace("  "," s").split(" ");

	// Split current message
	let check = myline.pop();
	let value = myline.pop();
	let label = myline.pop();

	// Regain checksum
	if (check == "s") check = " ";

	// Calcul checksum
	for (i = 0; i < label.length; i++) checksum += label.charCodeAt(i);
	for (i = 0; i < value.length; i++) checksum += value.charCodeAt(i);
	checksum = ((checksum%256) & 63) + 32;
	checksum = String.fromCharCode(checksum);

	// Checksum is not ok
	if (checksum != check ) {
		let error = {
			'topic':'',
			'payload': 'Bad Checksum "' + checksum + '" for label "' + label + '".'
		};
		return [null, error];
	}

	// Parse message
	let full = value;
	let trans = value;
	let name = label;

	// get readbale label
	if (typeof describe.names[label] == 'string') {
		name = describe.names[label];
	}

	// Convert numeric value to number
	if (!isNaN(trans) && isFinite(Number(trans))) trans = Number(trans);

	// OPTARIF : chars, length 4
	if (label == "OPTARIF") {
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof describe.optarif[value] === 'string' ? describe.optarif[value] : '';
	}
	// HHPHC : char, length 1
	else if (label == "HHPHC") {
		//trans = full = value.charCodeAt();
	}
	// PTEC : chars, length 4
	else if (label == "PTEC") {

		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof describe.ptec[value] === 'string' ? describe.ptec[value] : '';
	}

	// Add to output
	msg.payload[label] ={
		'raw': value,
		'value': trans,
		'full': full,
		'name': name
	};
}

let unit = global.get('units["' + msg.port + '"]', 'default');
if (typeof unit === 'object') {
	msg.payload['NAME'] = {
		'raw': unit['name'],
		'value': unit['name'],
		'full': unit['name'],
		'name': 'Nom'
	};
	msg.payload['LOCATION'] = {
		'raw': unit['location'],
		'value': unit['location'],
		'full': unit['location'],
		'name': 'Emplacement'
	};
	msg.payload['PORT'] = {
		'raw': unit['port'],
		'value': unit['port'],
		'full': unit['port'],
		'name': 'Port de communication'
	};
}

let controls = global.get('controls', 'default')||{};
controls[msg.port] = msg.payload;
global.set('controls', controls, 'default');

return [msg, null];

let res = {
    'topic': '',
    'ui_update': {},
    'payload': '-',
    'class': 'remove',
    'enabled': false
}

if (typeof msg.payload.IINST == 'object' && typeof msg.payload.ISOUSC == 'object') {
    res = {
        'topic': '',
        'ui_update': {
            'label': msg.payload.IINST.name + ' :',
            'gtype': 'gauge-half',
            'gstyle': 'rounded',
            'min': 0,
            'max': msg.payload.ISOUSC.value + 2,
            'segments': [
                { 'color': 'blue', 'from': 0},
                { 'color': 'green', 'from': Math.floor(msg.payload.ISOUSC.value / 3) },
                { 'color': 'orange', 'from': Math.floor(msg.payload.ISOUSC.value * 2 / 3) },
                { 'color': 'red', 'from': msg.payload.ISOUSC.value }
            ],
            'units': 'Ampère'
        },
        'payload': msg.payload.IINST.value,
        'class': '',
        'enabled': true
    };
}

return res;

let voltage = 240;
let res = {
    'topic': '',
    'payload': '-',
    'class': 'remove',
    'enabled': false
}

if (typeof msg.payload.PAPP == 'object' && typeof msg.payload.ISOUSC == 'object') {
    res = {
        'topic': '',
        'ui_update': {
            'label': msg.payload.PAPP.name + ' :',
            'gtype': 'gauge-half',
            'gstyle': 'rounded',
            'min': 0,
            'max': (msg.payload.ISOUSC.value + 2) * voltage,
            'segments': [
                { 'color': 'blue', 'from': 0},
                { 'color': 'green', 'from': Math.floor(msg.payload.ISOUSC.value * voltage  / 3) },
                { 'color': 'orange', 'from': Math.floor(msg.payload.ISOUSC.value * voltage * 2 / 3) },
                { 'color': 'red', 'from': msg.payload.ISOUSC.value * voltage }
            ],
            'units': 'VA'
        },
        'payload': msg.payload.PAPP.value,
        'class': '',
        'enabled': true
    };
}

return res;

msg.broker = {};

let mqtt = global.get('mqtt', 'default');
if (typeof mqtt == 'object' && mqtt.enabled == true) {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker.broker = mqtt.host;
        msg.broker.port = mqtt.port;
        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.broker.force = true;
        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        return msg;
    } else {
        global.set('mqtt["enabled"]', false, 'default');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
}

msg.action = 'disconnect';

return msg;

