.v-card .remove,
.v-card-text .remove {
    display: none !important;
    visibility: hidden;
    color: transparent !important;
}

.v-table__wrapper table thead {
    display: none !important;
}
tbody td[data-column-key=lbl] {
    font-weight: bold !important;
}

.v-tab-item--selected {
    color: #0094ce !important;
}

.v-main {
    padding-bottom: 2em;
}
#app-bar-actions img {
    margin-right: 20px;
}
.ui-title span {
    font-size: 1.4rem !important;
    font-weight: normal !important;
    padding: 0;
    color: #0094ce;
}

.nrdb-ui-group {
    border-radius: 4px;
    box-shadow: 3px 2px 2px rgba(0, 55, 77, 0.25);
}
.oe_nav {
    background: rgb(var(--v-theme-navigation-background));
}
#oe_header {
    border: none;
    padding-left: 1em;
    background: rgb(var(--v-theme-navigation-background));
}
.v-application {
    border-top: 1px solid #CCCCCC;
    margin-top: -1px;
}

