flow.set('current_tic', '', 'default');

msg.payload = '';
msg.class = '';
msg.enabled = true;
msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'name'
}];

let i = 1;
let units = global.get('units', 'default');
if (typeof units === 'object') {
    for(const port in units) {
        msg.options[i++] = {
            'label': units[port]['name'] + ' - ' + units[port]['location'] + '  - ' + port,
            'value': port,
            'dropdown': 'name'
        }
    }
}

if (i == 1) {
    node.send([null, null]);
}
else if (i == 2) {
    msg.payload = msg.options[1]['value'];
    node.send([msg, null]);
    msg.class = 'remove';
    msg.enlabed = false;
    node.send([null, msg]);
}
else {
    node.send([null, msg]);
}

return;

// on unwanted state, stop here
if (msg.payload.match((new RegExp('^(connect|change|lost)$'))) === null) {
    return;
}

// on connect or lost connection, go to auth page
if (msg.payload === 'connect' || msg.payload === 'lost') {
    msg.payload = 'chart';

    return [null, msg];
}

// ui main
msg.version = global.get('describe.app.version', 'default');
msg.title = global.get('describe.app.title', 'default');
msg.full = msg.title + ' v' + msg.version;
msg.git = "https://github.com/JcDenis/" + global.get('describe.app.git', 'default');
msg.lang = 'FR-fr';

// ui menu
msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};
let s =0;
let pages = global.get('describe.hmi', 'default') || {};
for (const tab in pages) {
    msg.menus[tab] = true;
    msg.titles[tab] = pages[tab];
    msg.payload.pages.show[s++] = tab;

    if (tab === msg.tab) {
        msg.title = msg.title + ' - ' + pages[tab];
    }
}

return [msg, null];

if (msg.payload !== '' && typeof global.get('describe.hmi["' + msg.payload + '"]', 'default') === 'string') {
    msg.tab = msg.payload;
    msg.name = global.get('describe.hmi["' + msg.payload + '"]', 'default');
    msg.payload = 'change';

    return msg;
}

return;

let units = global.get('units', 'default') || {};
let size = Object.keys(units).length;
if (size < 2) {
    msg.class = '';
    msg.enabled = true;
    msg.payload = {
        'name': 'Linky_' + size,
        'location': 'Maison',
        'port': size
    }
} else {
    msg.class = 'remove';
    msg.enabled = false;
    msg.payload = {};
}

return msg;

if (typeof msg.payload === 'object') {
    let describe = global.get('describe', 'default') || {};
    describe.app = {
        'title': msg.payload.description,
        'version' : msg.payload.version,
        'git': msg.payload.name
    };
    global.set('describe', describe, 'default');
}
return msg;
